pub const FS_INSPECT_STRUCTURE_XFS_RMAPBT_BLOCK: u32 = 91;
/// An XFS superblock (primary or secondary).
pub const FS_INSPECT_STRUCTURE_XFS_SUPERBLOCK: u32 = 92;
/// An XFS symbolic link block.
pub const FS_INSPECT_STRUCTURE_XFS_SYMLINK_BLOCK: u32 = 93;
/// A ZFS block, checked against the checksum in its block pointer.
pub const FS_INSPECT_STRUCTURE_ZFS_BLOCK: u32 = 94;
/// A ZFS list of freed blocks still allocated (pending frees, background destroys) that cannot
/// be read.
pub const FS_INSPECT_STRUCTURE_ZFS_BLOCK_LIST: u32 = 95;
/// A ZFS vdev label.
pub const FS_INSPECT_STRUCTURE_ZFS_LABEL: u32 = 96;
/// A ZFS raidz parity column.
pub const FS_INSPECT_STRUCTURE_ZFS_RAIDZ_PARITY: u32 = 97;
/// A ZFS uberblock.
pub const FS_INSPECT_STRUCTURE_ZFS_UBERBLOCK: u32 = 98;

// Symlinks (export symlink policy): FS_INSPECT_EXPORT_SYMLINKS_*.
/// Make a link with the same target.
pub const FS_INSPECT_EXPORT_SYMLINKS_PRESERVE: u32 = 1;
/// Leave it out (not reported).
pub const FS_INSPECT_EXPORT_SYMLINKS_SKIP: u32 = 2;

// VolumeLocationKind (volume location): FS_INSPECT_LOCATION_*.
/// Bytes `range` of a device of the set: a partition (or the whole device when it has no
/// partition table), of a disk or of a logical volume. A logical volume that cannot be read is
/// listed whole (from 0, its size).
pub const FS_INSPECT_LOCATION_DEVICE: u32 = 1;
/// A ZFS pool, read from its leaves (`fs_inspect_containers_members` of `container`): no linear
/// address space of its own; `fs_inspect_volume_members` are its leaves.
pub const FS_INSPECT_LOCATION_POOL: u32 = 2;

// VolumeRole (volume role): FS_INSPECT_VOLUME_ROLE_*.
/// The root file system of a macOS install (sealed and read-only from macOS 11).
pub const FS_INSPECT_VOLUME_ROLE_SYSTEM: u32 = 1;
/// Users' home directories.
pub const FS_INSPECT_VOLUME_ROLE_USER: u32 = 2;
/// The recovery system.
pub const FS_INSPECT_VOLUME_ROLE_RECOVERY: u32 = 3;
/// Swap space (`/private/var/vm`).
pub const FS_INSPECT_VOLUME_ROLE_VM: u32 = 4;
/// What the boot needs before the system volume is unlocked.
pub const FS_INSPECT_VOLUME_ROLE_PREBOOT: u32 = 5;
/// The system installer.
pub const FS_INSPECT_VOLUME_ROLE_INSTALLER: u32 = 6;
/// The writable data of a macOS install, paired with its system volume.
pub const FS_INSPECT_VOLUME_ROLE_DATA: u32 = 7;
/// Baseband firmware data.
pub const FS_INSPECT_VOLUME_ROLE_BASEBAND: u32 = 8;
/// Software update data.
pub const FS_INSPECT_VOLUME_ROLE_UPDATE: u32 = 9;
/// The secure enclave's storage (xART).
pub const FS_INSPECT_VOLUME_ROLE_XART: u32 = 10;
/// Hardware data.
pub const FS_INSPECT_VOLUME_ROLE_HARDWARE: u32 = 11;
/// Time Machine backups.
pub const FS_INSPECT_VOLUME_ROLE_BACKUP: u32 = 12;
/// Enterprise data.
pub const FS_INSPECT_VOLUME_ROLE_ENTERPRISE: u32 = 13;
/// What the login window needs before a user logs in.
pub const FS_INSPECT_VOLUME_ROLE_PRELOGIN: u32 = 14;

// VolumeStateKind (volume state): FS_INSPECT_VOLUME_STATE_*.
/// Consistent on disk: nothing to replay.
pub const FS_INSPECT_VOLUME_STATE_CLEAN: u32 = 1;
/// Inconsistent on disk (a crash-consistent snapshot); its log was replayed in memory, and the
/// map and browsing read what recovery leaves.
pub const FS_INSPECT_VOLUME_STATE_RECOVERED: u32 = 2;
/// Inconsistent on disk (`why`) and read as it is, with the file system's conservative rules:
/// `allocation_covered` tells whether the map still includes everything recovery would allocate
/// (otherwise a block allocated only in the log may be reported unused).
pub const FS_INSPECT_VOLUME_STATE_INCONSISTENT: u32 = 3;
/// The file system keeps no clean / dirty state this library reads, or it could not be read
/// (`why`).
pub const FS_INSPECT_VOLUME_STATE_UNKNOWN: u32 = 4;

// VolumeTail (volume tail): FS_INSPECT_VOLUME_TAIL_*.
/// Nowhere: the source is the volume's size, and a shorter one is refused.
pub const FS_INSPECT_VOLUME_TAIL_EXACT: u32 = 1;
/// The volume's own place on its device: the source may be shorter than the volume (a snapshot
/// of a volume grown since), and the rest of the volume is read where the set reads it without
/// the source.
pub const FS_INSPECT_VOLUME_TAIL_DEVICE: u32 = 2;

// XattrNs (xattr namespace): FS_INSPECT_XATTR_NS_*.
/// `user.`: set by users.
pub const FS_INSPECT_XATTR_NS_USER: u32 = 1;
/// `trusted.`: set by privileged processes.
pub const FS_INSPECT_XATTR_NS_TRUSTED: u32 = 2;
/// `security.`: security modules' labels (SELinux, capabilities).
pub const FS_INSPECT_XATTR_NS_SECURITY: u32 = 3;
/// `system.`: the file system's own (POSIX ACLs).
pub const FS_INSPECT_XATTR_NS_SYSTEM: u32 = 4;
/// `com.apple.*`.
pub const FS_INSPECT_XATTR_NS_APPLE: u32 = 5;
/// Another namespace, or a file system without namespaces.
pub const FS_INSPECT_XATTR_NS_OTHER: u32 = 6;

// ZipCompression (zip compression): FS_INSPECT_ZIP_*.
/// Stored as they are.
pub const FS_INSPECT_ZIP_STORE: u32 = 1;
/// Deflate.
pub const FS_INSPECT_ZIP_DEFLATE: u32 = 2;
